// For #WCCChallenge << succulent >>
// Join the discord! (https://discord.gg/PrnrhZQrb9)
//
// Just playing around with geometries in 3D. Liked the transparent look so decided to make it crystal-like

var PHI = (1 + Math.sqrt(5)) / 2
function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL)
  angleModecolorModebackground('#fffbe6')
}

function draw() {
  background('#fffbe6')
  let w = max(width, height)
  orbitControl()
  let s = 30 // Initial point
  let t = 100 // Number of steps (leaves)
  let d = 0.5 // Distance multiplier
  let leafWidth = w / 15
  let leafHeight = leafWidth * 2
  let leafDepth = leafWidth / 2

  specularMaterial(color('#4b8a5f'))
  pointLight(color('#c5d419'), -width/3, -height, 0)
  pointLight(color('#563d7c'), 0, -leafHeight * 1.5, 0)
  rotateX(-45)
	translate(0, -w/8, 0)
  rotateY(0.2 * frameCount)
  for (let i = s; i < s + t; i = i + 1) {
    let a = (i * 5 * PHI) % 360
    fill(map(a, 0, 360, 100, 140), map(a, 0, 360, 50, 90), map(a, 0, 360, 40, 80), 0.3)
    stroke(map(a, 0, 360, 140, 100), map(a, 0, 360, 30, 10), map(a, 0, 360, 100, 80))
    strokeWeight(map(i, s, s+t, 1, 5))
    rotateY(360 * PHI)
    push()
    translate(s + i * d, map(i, s, s+t, 0, 0.5 * leafHeight, 0), 0)
    scale(
      map(i, s, s + t, 1, map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 3, 5, true)),
      map(i, s, s + t, 0.5, 5),
      map(i, s, s + t, 1, 6)
    )
    rotateY(-90)
    rotateX(map(i, s, s + t, 0, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 90, 115, true)))
    drawLeaf(leafWidth, leafHeight, leafDepth)
    pop()
  }

  ambientMaterial('white')
  fill(0, 0, 100, 0.2)
  noStroke()
  let potWidth = (leafHeight*3/8) * 5
  let potHeight = potWidth * 3/4
  let potY = leafHeight*3/4 + leafDepth/2
  push()
  translate(0, potY + (potHeight/5)/2, 0)
  cylinder(potWidth, potHeight / 5)
  pop()
  push()
  translate(0, potY + potHeight / 2, 0)
  cylinder(potWidth * 5/6, potHeight)
  pop()
}

var buildSurfaces = (builder, shapes) => {
  for (let shape of shapes) {
    builder.beginShape()
    for (let points of shape) { builder.vertex(...points) }
    builder.endShape(CLOSE)
  }
}

var _leaf
var drawLeaf = (w, h, d) => {
  if (!_leaf) {
    _leaf = buildGeometry('succulent', (builder) => {
      builder.translate(-w/2, -h/2, -d/2)
      buildSurfaces(builder, [
        [[w/2, 0, d], [w/2, h/2,  0], [0, h/2, d/2]],
        [[w/2, 0, d], [w, h/2, d/2], [w/2, h/2, 0]],
        [[0, h/2, d/2], [w/2, h/2, 0], [w/2, h*3/4, d]],
        [[w/2, h/2, 0], [w, h/2, d/2], [w/2, h*3/4, d]],
      ])
    })
  }
  model(_leaf)
}
